    <div class="juris-hero-media"><?php foreach($slides as $i=>$slide):?><img class="<?=$i===0?'hero-image':'juris-hero-image'?> <?=$i===0?'is-active':''?>" src="<?=e(safe_image($slide['image']))?>" alt="<?=e($slide['alt'])?>" aria-hidden="<?=$i===0?'false':'true'?>" width="1536" height="1024" <?=$i===0?'fetchpriority="high"':'loading="lazy"'?> data-slide-image="<?=$i?>"><?php endforeach;?></div>
    <div class="juris-hero-shade" aria-hidden="true"></div>
    <div class="container juris-hero-content">
        <div class="juris-hero-copy"><span class="eyebrow"><?=e(setting('hero_eyebrow'))?></span><h1 id="hero-title"><?=nl2br(e(setting('hero_title')))?></h1><div class="juris-hero-lead"><?=rich_text(setting('hero_text'))?></div><div class="juris-hero-actions"><a class="button" href="<?=e(safe_url(setting('hero_button_url')))?>"><?=e(setting('hero_button'))?> <?=icon('arrow')?></a><a class="button button-glass" href="<?=e(safe_url(setting('hero_secondary_url')))?>"><?=e(setting('hero_secondary'))?> <?=icon('arrow')?></a></div><?php if(setting('hero_note')):?><small class="juris-hero-note"><?=e(setting('hero_note'))?></small><?php endif;?></div>
        <?php if($heroPractices):?><nav class="juris-hero-expertise" aria-label="Öne çıkan çalışma alanları"><span><?=e(setting('practice_eyebrow'))?></span><?php foreach($heroPractices as $i=>$practice):?><a href="<?=e(entry_url($practice))?>"><small><?=sprintf('%02d',$i+1)?></small><?=e($practice['title'])?><?=icon('arrow')?></a><?php endforeach;?><a class="juris-hero-all" href="/calisma-alanlari"><?=e(ui('all_practices'))?> <?=icon('arrow')?></a></nav><?php endif;?>
    </div>
    <?php if(count($slides)>1):?><div class="juris-hero-pagination" role="group" aria-label="Ana görsel seçimi"><?php foreach($slides as $i=>$_):?><button type="button" data-slide-to="<?=$i?>" aria-label="<?=$i+1?>. görsel" aria-current="<?=$i===0?'true':'false'?>"><span></span></button><?php endforeach;?><button type="button" class="slider-pause" data-slider-pause data-pause-label="<?=e(ui('slider_pause'))?>" data-play-label="<?=e(ui('slider_play'))?>" aria-pressed="false"><?=e(ui('slider_pause'))?></button></div><?php endif;?>
