ntact-info"><div class="juris-contact-inner"><span class="eyebrow"><?=e(setting('brand_subtitle'))?></span><h2><?=e(ui('contact_info_title'))?></h2><p><?=e(ui('contact_info_text'))?></p><dl><div><dt><?=e(ui('contact_address_label'))?></dt><dd><?=nl2br(e(setting('address')))?></dd></div><?php if(setting('email')):?><div><dt><?=e(ui('contact_email_label'))?></dt><dd><a href="mailto:<?=e(setting('email'))?>"><?=e(setting('email'))?></a></dd></div><?php endif;if(setting('phone')):?><div><dt><?=e(ui('contact_phone_label'))?></dt><dd><a href="tel:<?=e(preg_replace('/[^+0-9]/','',setting('phone')))?>"><?=e(setting('phone'))?></a></dd></div><?php endif;?><div><dt><?=e(ui('contact_hours_label'))?></dt><dd><?=e(setting('office_hours'))?></dd></div></dl><a class="text-link" href="/iletisim"><?=e(setting('contact_button'))?> <?=icon('arrow')?></a></div></div></section>
